import React from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";

const Navbar = ({ loggedIn, setLoggedIn, visitedHome, interviewDone }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const isLanding = location.pathname === "/";

  const handleLogout = () => {
    setLoggedIn(false);
    navigate("/login");
  };

  return (
    <nav className="bg-blue-950 shadow-md py-4 px-8 flex justify-between items-center sticky top-0 z-50">
      <Link
        to="/"
        className="text-2xl font-bold text-blue-200 hover:text-white transition duration-300"
      >
        AI Interview Coach
      </Link>

      {!isLanding && (
        <div className="flex gap-6 items-center">
          {loggedIn ? (
            <>
              <Link to="/home" className="hover:text-blue-300">
                Home
              </Link>

              {visitedHome && (
                <Link to="/interview" className="hover:text-blue-300">
                  Interview
                </Link>
              )}

              {interviewDone && (
                <Link to="/feedback" className="hover:text-blue-300">
                  Feedback
                </Link>
              )}

              <button
                onClick={handleLogout}
                className="bg-blue-600 px-4 py-2 rounded-md hover:bg-blue-700 transition"
              >
                Logout
              </button>
            </>
          ) : (
            <>
              <Link to="/login" className="hover:text-blue-300">
                Login
              </Link>
              <Link to="/signup" className="hover:text-blue-300">
                Signup
              </Link>
            </>
          )}
        </div>
      )}
    </nav>
  );
};

export default Navbar;
